def find_bar(grid):
    """The list of colors of the solid multi-color bar (a small rectangle of distinct colors, repeated along one axis), plus its bbox (r0, c0, h, w); (None,) if absent."""
    H,W=len(grid),len(grid[0])
    for i in range(H):
        for j in range(W):
            v=grid[i][j]
            if not v: continue
            row=grid[i]
            ks=[x for x in range(W) if row[x]]
