                while j+ww<W and [grid[x][j+ww] for x in ks]==cl: ww+=1
                if ww>=2:
                    return cl,ks[0],j,len(ks),ww
    return (None,)

def components(grid):
    """The 4-connected same-color nonzero components as (color, cells) sorted by top row."""
    H,W=len(grid),len(grid[0])
    seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if grid[i][j] and not seen[i][j]:
                c=grid[i][j]; st=[(i,j)]; cells=[]; seen[i][j]=True
                while st:
                    y,x=st.pop(); cells.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
