                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and grid[ny][nx]==c:
                            seen[ny][nx]=True; st.append((ny,nx))
                comps.append((c,cells))
    comps.sort(key=lambda cc:min(y for y,_ in cc[1]))
    return comps

def pattern_of(cells):
    """The 0/1 bounding-box pattern of a component's cell list."""
    minr=min(y for y,_ in cells); minc=min(x for _,x in cells)
    h=max(y for y,_ in cells)-minr+1; w=max(x for _,x in cells)-minc+1
    cs=set(cells)
    return [[1 if (minr+r,minc+c) in cs else 0 for c in range(w)] for r in range(h)],minr,minc

def stamp(grid,pat,top,left,color):
    """Draw a 0/1 pattern onto the grid at (top,left) in the given color (0s are skipped)."""
    for r in range(len(pat)):
